<?php
declare(strict_types=1);namespace App\Services\Finance;use App\Models\Bank\BankTransaction;use App\Models\Finance\{StudentInvoice,StudentPayment,StudentVirtualAccount};use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;class BriReconciliationService{public function reconcile(BankTransaction $transaction,?int $actor):StudentPayment{return DB::transaction(function()use($transaction,$actor){$transaction=BankTransaction::lockForUpdate()->findOrFail($transaction->id);$existing=StudentPayment::where('bank_reference',$transaction->provider_reference?:$transaction->external_id)->first();if($existing)return $existing;$va=StudentVirtualAccount::where('virtual_account_number',$transaction->virtual_account_number?:$transaction->request_reference)->first();if(!$va)throw ValidationException::withMessages(['transaction'=>'VA tidak ditemukan.']);$invoice=$va->invoice_id?StudentInvoice::lockForUpdate()->find($va->invoice_id):StudentInvoice::where('student_id',$va->student_id)->whereIn('status',['issued','partial','overdue'])->where('outstanding_amount',$transaction->amount)->lockForUpdate()->sole();if(!$invoice)throw ValidationException::withMessages(['transaction'=>'Tagihan tidak ditemukan secara deterministik.']);if(bccomp((string)$transaction->amount,(string)$invoice->outstanding_amount,2)===1)throw ValidationException::withMessages(['transaction'=>'Nominal melebihi sisa tagihan dan wajib ditinjau manual.']);$payment=app(PaymentService::class)->record($invoice,['amount'=>$transaction->amount,'paid_at'=>$transaction->occurred_at??now(),'payment_method'=>$transaction->transaction_type==='qris_payment'?'bri_qris':'bri_briva','bank_reference'=>$transaction->provider_reference?:$transaction->external_id,'source'=>'bri_callback'],$actor);$transaction->update(['reconciled_at'=>now(),'status'=>'matched']);activity('bri-reconciliation')->performedOn($transaction)->log('Transaksi BRI direkonsiliasi.');return $payment;});}}
